  "A fork branches from the shared history into its own independent session — the original is left untouched. Send a first message to make the branch diverge now (otherwise it looks identical to a plain resume until you continue it).": "分叉会从共享历史分出一个独立会话——原会话不受影响。发送第一条消息让分支立即分化（否则在继续之前它看起来与普通恢复相同）。",
  "Forking from the selected message — the new session contains the conversation up to and including that point, then continues with your message. The original is left untouched.": "从所选消息处分叉——新会话包含截至该消息的对话，然后以你的消息继续。原会话不受影响。",
