  "Agent memory files (reads AND writes)": "Agent 记忆文件（读和写）",
  "Memory update": "记忆更新",
  "Memory read": "记忆读取",
  "Copying {name}…": "正在复制 {name}…",
  "Moving {name}…": "正在移动 {name}…",
  "MCP tool calls (any server)": "MCP 工具调用（所有服务器）",
  "{n} MCP": "{n} 次 MCP",
  "System": "系统",
  "Collecting samples — history appears after a few minutes.": "正在采样——几分钟后出现历史曲线。",
  "Memory": "内存",
  "Load": "负载",
  "Disk (workspace)": "磁盘（工作区）",
  "Top consumer:": "最大占用：",
  "Close to the container limit — the kernel may OOM-kill the whole instance (all sessions die). Stop the top consumers below.": "接近容器内存上限——内核可能 OOM 击杀整个实例（所有会话一起死）。请停掉下方占用最高的进程。",
  "cgroup total {raw} incl. {cache} file cache (reclaimable, not counted above)": "cgroup 总计 {raw}，其中 {cache} 是文件缓存（可回收，未计入上方）",
  "Memory at {pct}% of the container limit — an OOM kill would end EVERY session.": "内存已达容器上限的 {pct}%——一旦 OOM 击杀，所有会话都会终结。",
  "· logged in on {host}": "· 已在 {host} 登录",
  "not logged in on {host}": "未在 {host} 登录",
  "This account holds its own login ON {host} (minted there, never leaves it) — sessions on {host} picking it use that login.": "这个账号在 {host} 上有自己的独立登录（在那台机器上生成、永不离开）——{host} 上的会话选它即使用该登录。",
  "Log in on {host} as this account…": "以此账号在 {host} 上登录…",
  "Sign in as “{name}” in the terminal — this login lives ON {host} only; the machine’s own login is untouched.": "请在终端里用“{name}”登录——该登录只保存在 {host} 上；机器自身的登录不受影响。",
  "Runs on this machine only. For {host}: use “Log in on {host} as this account…” in the ⋯ menu (a per-account login held on the host), or enable Settings → “Ship subscription logins to remote hosts.”": "只在本机运行。要用于 {host}：用 ⋯ 菜单里的“以此账号在 {host} 上登录…”（登录保存在那台机器上），或开启 设置 → “将订阅登录下发到远程主机”。",
  "Same account as {host}’s current CLI login — sessions on {host} picking it run on the host’s own login directly (nothing is shipped).": "与 {host} 当前的 CLI 登录是同一个账号——在 {host} 上的会话选它会直接使用主机自身登录（不下发任何凭据）。",
  "· = {host}’s own login": "· 即 {host} 自身登录",
  "Switch {host}’s own login?": "切换 {host} 自身的登录？",
  "This opens claude /login ON {host} and REPLACES that machine’s current CLI login. VibeSpace’s named accounts are untouched — to add a switchable account instead, use “+ Add account…”.": "这会在 {host} 上打开 claude /login，并替换那台机器当前的 CLI 登录。VibeSpace 里的命名账号不受影响——若想添加一个可切换的账号（不动机器登录），请用“+ 添加账号…”。",
  "The Console API key currently on it (…{tail}) will be imported into VibeSpace first so it isn’t lost.": "它当前的 Console API key（…{tail}）会先导入 VibeSpace，避免丢失。",
  "This opens codex login ON {host} and REPLACES that machine’s current ChatGPT login. VibeSpace’s named accounts are untouched — to add a switchable account instead, use “+ Add ChatGPT account…”.": "这会在 {host} 上打开 codex login，并替换那台机器当前的 ChatGPT 登录。VibeSpace 里的命名账号不受影响——若想添加一个可切换的账号（不动机器登录），请用“+ 添加 ChatGPT 账号…”。",
  "Restart in bypassPermissions?": "以 bypassPermissions 重启？",
  "The CLI refuses switching a running session to bypassPermissions (it must be launched with that mode). Restart this conversation with bypassPermissions? The history is kept — it resumes where you left off.": "CLI 拒绝把运行中的会话切换到 bypassPermissions（必须以该模式启动）。要以 bypassPermissions 重启这个对话吗？历史会保留——从当前位置继续。",
  "Restart session": "重启会话",
  "Permission mode unchanged": "权限模式未变更",
  "Permission mode change refused by the CLI": "CLI 拒绝了权限模式变更",
  "Session id not known yet — try again after the first reply": "会话 id 尚未确定——等第一条回复后再试",
  "login changed — ⟳ to confirm": "登录已变更——点 ⟳ 确认",
  "The login on this machine changed after the last identity/quota refresh — the cached account info may belong to the previous login. Press ⟳ to confirm.": "这台机器的登录在上次身份/配额刷新之后发生了变更——缓存的账号信息可能属于之前的登录。点 ⟳ 确认。",
  "Confirm identity + quota of {host}’s own login (one on-demand read of its token — never scheduled)": "确认 {host} 自身登录的身份与配额（按需读取一次其 token——绝不定时轮询）",
  "✓ Login on {host} updated": "✓ {host} 上的登录已更新",
  "Refreshed less than a minute ago — try again shortly": "一分钟内已刷新过——稍后再试",
  "Refresh failed": "刷新失败",
  "Already logged in as this account ON {host}? Then pick “CLI login @ {host}” when switching the session’s billing — that uses the host’s own login.": "已经在 {host} 上登录了这个账号？切换会话计费时选“CLI login @ {host}”即可——那会使用主机自己的登录。",
  "This stored login can’t ship to {host}. If you’ve logged this account in ON {host}, pick “CLI login @ {host}” above — that uses the host’s own login. (Or enable Settings → “Ship subscription logins to remote hosts”.)": "这个存储在本机的登录无法下发到 {host}。如果你已在 {host} 上登录了该账号，选上面的“CLI login @ {host}”——那会使用主机自己的登录。（或开启 设置 → “将订阅登录下发到远程主机”。）",
  "This macOS Keychain-backed login stays on this machine. Log in as this account on {host} instead; copying it can invalidate rotating OAuth credentials.": "这个由 macOS 钥匙串支持的登录只保留在本机。请改为在 {host} 上登录此账号；复制它可能使轮换中的 OAuth 凭据失效。",
  "Attached pages ({n})": "文档页面图（{n}）",
  "off by default; encrypted with a passphrase. The file lets anyone who has it (and the passphrase) log in / use your agent accounts. Treat it like a key.": "默认关闭；用口令加密。拥有该文件（及口令）的任何人都可登录 / 使用你的 agent 账号。请像对待密钥一样对待它。",
  "optional": "可选",
  "or browse files first": "或先浏览文件",
  "other key source": "其他密钥来源",
  "password hash — same password works after import": "密码哈希——导入后同一密码依然可用",
  "ready": "就绪",
