  "will be created at the next start — or press Apply": "将在下次启动时创建——或点击“应用”",
  "will be created at the next tool install or session start on that machine": "将在那台机器下次安装工具或启动会话时创建",
  "{dir} not found — the CLI has not run on this machine, so nothing is written": "{dir} 不存在——这台机器上还没运行过该 CLI，因此不写入任何内容",
  "{label}: will be created at the next start — or press Apply": "{label}：将在下次启动时创建——或点击“应用”",
  "{label}: the CLI has not run on this machine": "{label}：这台机器上还没运行过该 CLI",
  "Create the file now and register VibeSpace in it": "立即创建该文件并在其中注册 VibeSpace",
  "Could not apply the CLI config — {reason}": "无法应用 CLI 配置——{reason}",
  "CLI config applied on this machine": "已在本机应用 CLI 配置",
  "1 running {label} conversation started before VibeSpace registered its hooks — Terminate and Resume it to give its agent the VibeSpace tools": "有 1 个正在运行的 {label} 对话早于 VibeSpace 注册 hook 启动——终止并恢复它，它的 agent 才能获得 VibeSpace 工具",
  "{n} running {label} conversations started before VibeSpace registered its hooks — Terminate and Resume them to give their agents the VibeSpace tools": "有 {n} 个正在运行的 {label} 对话早于 VibeSpace 注册 hook 启动——终止并恢复它们，它们的 agent 才能获得 VibeSpace 工具",
  "VibeSpace created {file} (the CLI had never written one) and registered its hooks.": "VibeSpace 创建了 {file}（CLI 从未写过这个文件）并在其中注册了 hook。",
  "A running conversation keeps the hooks it started with, so its agent has no VibeSpace tools context, task context or bookkeeping until it is restarted.": "正在运行的对话沿用它启动时的 hook，所以在重启之前，它的 agent 没有 VibeSpace 工具说明、任务上下文和记账提醒。",
