  "{n} stopped · see Folders": "{n} 个已停止 · 见文件夹",
  "{n} theme(s)": "{n} 个主题",
  "{n} total": "共 {n} 个",
  "{n} waiting for input": "{n} 个等待输入",
  "{n} windows": "{n} 个窗口",
  "{pct}% used": "已用 {pct}%",
  "{rows}×{cols} grid": "{rows}×{cols} 网格",
  "{state} — {activity} (observed by VibeSpace; the agent can set its own state with vibespace-status). Click to set manually.": "{state} — {activity}（由 VibeSpace 观察；agent 可用 vibespace-status 设置自己的状态）。点击手动设置。",
  "~/.claude/.credentials.json — no re-login on the new instance": "~/.claude/.credentials.json——新实例上无需重新登录",
  "Re-login on this machine…": "在本机重新登录…",
  "Log in on this machine…": "在本机登录…",
  "A terminal opened — sign in as “{name}”. Only this account’s login is refreshed; every other login is untouched.": "已打开一个终端——请以“{name}”身份登录。只会刷新这个账号的登录，其它登录一律不受影响。",
  "✓ “{name}” signed in again": "✓ “{name}” 已重新登录",
  "The login belongs to a DIFFERENT account ({email}) — saved as the new entry “{new}”. “{name}” stays signed out.": "这次登录属于另一个账号（{email}）——已另存为新条目“{new}”。“{name}”保持登出状态。",
  "The login belongs to “{other}” ({email}) — its login was refreshed there instead. “{name}” stays signed out.": "这次登录属于“{other}”（{email}）——已把该账号的登录刷新到它自己的条目上。“{name}”保持登出状态。",
  "Switched back to Local — the previously selected remote host no longer exists.": "已切回本机——之前选择的远程主机已不存在。",
  "The machine’s global CLI login is this same subscription — its quota is shown merged here.": "本机全局 CLI 登录与该账号同属一个订阅——配额已合并显示。",
  "The CLI config file records {cfg} — residue of the most recent account login (relocated logins still write their identity into the global config). The active token belongs to {actual}, whose quota is shown. No action needed.": "CLI 配置文件里记录的 {cfg} 只是最近一次添加/登录账号时留下的记录残留（重定位登录仍会把身份写进全局配置）。实际生效的 token 属于 {actual}，显示的即其配额。无需任何处理。",
  "(+{n} more lines — open the file to see all)": "（还有 {n} 行——打开文件查看全部）",
  "{n} urgent": "{n} 条紧急",
  "{n} high": "{n} 条高优先级",
  "{n} normal": "{n} 条普通",
  "waiting on you": "等你处理",
  "⚠ Subscription signed out (a Console login replaced it) — pies show its last-known quota. API-billed sessions never appear here.": "⚠ 订阅已登出（已被 Console 登录替换）——环形图显示其最后已知的配额。按 API 计费的会话不会出现在这里。",
  "✓ {n} more completed…": "✓ 另有 {n} 个已完成…",
  "Grid snap off": "已关闭网格吸附",
  "Shake to bypass snap": "摇晃取消吸附",
  "Shake a window vigorously for ~1 second while dragging to turn off grid/edge snap for the rest of that drag (a mouse-only alternative to holding Alt)": "拖动时剧烈摇晃窗口约 1 秒，即可在本次拖动的剩余过程中关闭网格/边缘吸附（无需键盘，相当于按住 Alt 的替代方式）",
  "Shake duration (seconds)": "摇晃触发时长（秒）",
  "How long you must keep shaking before grid snap turns off. Lower = triggers faster (but easier to trigger by accident).": "需要持续摇晃多久才关闭网格吸附。数值越小触发越快（但也更容易误触发）。",
  "Task Group folder ({name})": "任务组文件夹（{name}）",
  "In a Task Group folder — {n} session(s) here": "位于任务组文件夹内——此处已有 {n} 个会话",
