  "A terminal opened — sign in with the ChatGPT account you want to add. Your other logins are untouched; VibeSpace captures it automatically.": "已打开一个终端——用你想添加的 ChatGPT 账号登录。你其它的登录不受影响；VibeSpace 会自动捕获。",
  "Add ChatGPT account": "添加 ChatGPT 账号",
  "Add ChatGPT account…": "添加 ChatGPT 账号…",
  "CLI login on {host}": "{host} 上的 CLI 登录",
  "ChatGPT / OpenAI accounts": "ChatGPT / OpenAI 账号",
  "ChatGPT login": "ChatGPT 登录",
  "ChatGPT login (on the host)": "ChatGPT 登录（在远程主机上）",
  "Connect cloud folders and shared datasets": "连接云端文件夹与共享数据集",
  "Copy the Console key found on {host} (…{tail}) into VibeSpace so any machine can use it": "将在 {host} 上发现的 Console 密钥（…{tail}）复制到 VibeSpace，任何机器都能使用",
  "Each Codex session can pick its ChatGPT login (New Session dialog / card ⚙). Held in isolated logins, switchable per session; threads stay shared.": "每个 Codex 会话都可选择自己的 ChatGPT 登录（新建会话对话框 / 卡片 ⚙）。以隔离登录保存，可按会话切换；线程仍然共享。",
  "Import its key": "导入它的密钥",
  "Log in on {host}…": "在 {host} 上登录…",
  "Logs in ON the selected remote host (its own login, not VibeSpace)": "在所选远程主机上登录（是它自己的登录，不属于 VibeSpace）",
  "Name this account (e.g. Work ChatGPT, Personal)": "为此账号命名（例如：工作 ChatGPT、个人）",
  "Opens a terminal ON {host} — this login lands on that machine, not in VibeSpace": "在 {host} 上打开一个终端——此登录落在那台机器上，不在 VibeSpace 中",
  "Remove \"{name}\" from VibeSpace? Sessions already running keep working.": "从 VibeSpace 中移除“{name}”？已在运行的会话不受影响。",
  "Sign in another ChatGPT account — stored in VibeSpace (not on any one machine), switchable per session": "登录另一个 ChatGPT 账号——保存在 VibeSpace 中（不落在任何一台机器上），可按会话切换",
  "Storage": "存储",
  "The CLI’s own global login on this machine": "这台机器上 CLI 自身的全局登录",
  "This account isn’t signed in yet — use “Add ChatGPT account…” to finish the login first.": "此账号尚未登录——请先用“添加 ChatGPT 账号…”完成登录。",
  "This machine's own login — lives on {host}, not in VibeSpace": "这台机器自己的登录——保存在 {host} 上，不在 VibeSpace 中",
  "account": "账号",
  "e.g. Work ChatGPT": "例如：工作 ChatGPT",
  "model-name": "模型名称",
  "remote host": "远程主机",
  "unreachable": "无法连接",
  "Ship subscription logins to remote hosts": "将订阅登录下发到远程主机",
  "OFF (recommended): a subscription (Pro/Max) account can only run on THIS machine; for a remote host, log in on the host instead. Turning this ON copies the subscription’s login to the remote host — its token then appears from that host’s IP (often a datacenter), which can look like account abuse to Anthropic and risk a ban. API-key accounts are always allowed on remote hosts and are unaffected by this.": "关闭(推荐):订阅(Pro/Max)账号只能在本机运行;要在远程主机上跑,请改为在该主机上登录。开启后会把订阅的登录复制到远程主机——它的 token 就会从那台主机的 IP(通常是数据中心)出现,可能被 Anthropic 判定为账号滥用、面临封号风险。API key 账号始终允许在远程主机使用,不受此项影响。",
  "⚠ Actively poll subscription usage (automation risk)": "⚠ 主动轮询订阅用量(有自动化风险)",
  "OFF (recommended): usage bars are captured passively from your live terminal sessions — VibeSpace never contacts Anthropic on its own. Turning this ON restores the old behavior: the server calls Anthropic’s usage endpoint on a ~90s timer with each subscription’s token, even for idle accounts. That off-CLI, fixed-cadence, non-human traffic is exactly what can get a Pro/Max account flagged as automated and BANNED — a real account was banned+refunded for this. Only enable it if you accept that risk (e.g. to see live usage for chat-only or idle accounts).": "关闭(推荐):用量条从你的实时终端会话被动捕获——VibeSpace 绝不主动联系 Anthropic。开启后恢复旧行为:服务器每约 90 秒用每个订阅的 token 调用 Anthropic 用量接口,连闲置账号也照打。这种绕过 CLI、固定节律、非人类的流量,正是会让 Pro/Max 账号被判定为自动化并封号的行为——已有真实账号因此被封+退款。仅在你接受该风险时开启(例如为了看聊天专用或闲置账号的实时用量)。",
  "Are you sure?": "确定吗?",
  "Enable anyway": "仍然开启",
  "Enable this setting?": "开启此设置?",
  "API key — stored in VibeSpace, runs on any machine": "API 密钥——保存在 VibeSpace,可在任意机器上运行",
  "ChatGPT account — runs on this machine (or a host you log into)": "ChatGPT 账号——只在本机运行(或你已登录的主机上)",
  "Runs on this machine only. For {host}, log in on the host — or enable Settings → “Ship subscription logins to remote hosts.”": "仅在本机运行。要用于 {host},请在该主机上登录——或在 设置 → “将订阅登录下发到远程主机” 中开启。",
  "Subscription (Pro/Max) — runs on this machine (or a host you log into)": "订阅(Pro/Max)——只在本机运行(或你已登录的主机上)",
  "· this machine only": "· 仅本机",
  "“{name}” runs on this machine only. For {host}, use “Log in on host…” on the CLI-login row, or turn on Settings → “Ship subscription logins to remote hosts.”": "“{name}”只在本机运行。要用于 {host},请在 CLI 登录行用“在主机上登录…”,或在 设置 → “将订阅登录下发到远程主机” 中开启。",
