  "Hide empty thinking blocks": "隐藏空的思考块",
  "Thinking cards with no visible text (redacted or zero-length thinking) are hidden. They never count toward or break run collapsing. Turn off to see every thinking card — applies to open chats instantly.": "隐藏没有可见文本的思考卡片(被遮蔽或零长度的思考)。它们不参与也不打断连续折叠。关闭后显示所有思考卡片 — 对已打开的会话即时生效。",
  "Credential only — this token can’t open the storage root; add submounts (specific buckets/paths) under it.": "仅凭据 — 此 token 打不开存储根目录;在其下添加子挂载(具体 bucket/路径)。",
  "Add a submount (a specific bucket/path of this storage)": "添加子挂载(此存储下的具体 bucket/路径)",
  "This storage type doesn’t support submounts": "该存储类型不支持子挂载",
  "New submount under \"{name}\"": "在 \"{name}\" 下新建子挂载",
  "What happens when closing a session window: detach and keep it running (default — the session stays in the sidebar for re-attach), or terminate it. Automation helper terminals always terminate.": "关闭会话窗口时的行为：分离并保持运行（默认——会话留在侧边栏可随时重新打开），或终止会话。自动化辅助终端总是终止。",
  "A server over SSH (SFTP)": "SSH 服务器 (SFTP)",
  "Access key": "Access Key",
  "Advanced: an absolute path if you need it in a specific place.": "高级：如需放在特定位置，填绝对路径。",
  "Advanced: you can also paste the JSON from `rclone authorize \"drive\"` run elsewhere.": "高级：也可粘贴在别处运行 `rclone authorize \"drive\"` 得到的 JSON。",
  "Another VibeSpace": "另一个 VibeSpace",
  "Any backend rclone supports — see rclone.org/docs. Params below map to that backend's config keys.": "rclone 支持的任意后端——见 rclone.org/docs。下方参数对应该后端的配置项。",
  "Ask the other VibeSpace to create one under Storage → “Share a local folder”.": "请对方在其 VibeSpace 的 存储 → “分享本机文件夹” 里创建一个。",
