  "Direct CephFS link — embeds a scoped key; only works inside this cluster. Send over company chat only; Revoke under Bridge tokens.": "CephFS 直连链接——内嵌受限密钥，仅本集群内可用。只通过公司内部渠道发送；可在“桥接令牌”下撤销。",
