  "Join your tailnet — reach home/LAN machines (NAS, dev boxes) from this instance. State persists across container rebuilds; no re-login.": "加入你的 tailnet——从此实例访问家里/局域网的机器（NAS、开发机）。状态跨容器重建保留，无需重新登录。",
