  "No remote machines yet — add one in the Remote tab": "还没有远程机器 — 在“远程”标签页添加",
  "Pair a device (no ssh — it dials out)": "配对设备（无需 ssh — 它主动拨出）",
  "Pair a device": "配对设备",
  "Re-paired \"{id}\" — the connected device was updated in place; the new pairing takes effect within ~30s. Run the command below only if the dot doesn’t come back:": "已重新配对 \"{id}\"——在线设备已原地更新，新配对约 30 秒内生效。只有当绿点没有回来时才需要在设备上运行下面的命令：",
  "Re-running the command on the device REPLACES its pairing with this instance. Pairing the same device with several VibeSpace instances is fine — each instance gets its own daemon on the device.": "在设备上重新运行该命令会【替换】它与本实例的配对。同一台设备与多个 VibeSpace 实例配对没有问题——每个实例在设备上有自己独立的 daemon。",
  "Device name": "设备名称",
  "Create pairing": "创建配对",
  "Pairing…": "配对中…",
  "Copy command": "复制命令",
  "Command copied": "命令已复制",
  "Group manager — may organize ALL Task Groups from its CLI (not just its own)": "组管理员——可通过其 CLI 管理所有任务组（不限于自己所属的）",
  "Globally enabled — a designated session can list/create/configure/bind EVERY group and act on any of them with --group (audited in each group's activity log). The agent is told about these powers on its next turn.": "全局已启用——被指定的会话可列出/创建/配置/绑定所有任务组，并用 --group 对任意组操作（记入各组活动日志）。agent 会在下一轮被告知这些权限。",
