  "vscode behavior: collapsing the sidebar leaves the 44px icon rail on screen — click any icon to expand back. Off = collapsing hides everything.": "vscode 行为：收起侧栏后 44px 图标栏仍留在屏幕上，点任意图标即可展开。关闭则收起时全部隐藏。",
