  "Couldn’t reach this session’s machine to check which accounts it can use — this row is a guess from cached data.": "无法连上此会话所在的机器以检查它能使用哪些账号——此行是根据缓存数据的猜测。",
  "Creating the session is taking unusually long — it may still be in progress; reloading the tab abandons it": "创建会话耗时异常——它可能仍在进行中；刷新此标签页会放弃它",
  "Custom OAuth client id (optional)": "自定义 OAuth client id(可选)",
  "Dial-out removed — \"{name}\" is a plain ssh machine again": "已移除拨出连接——“{name}”恢复为普通 ssh 机器",
  "Dial-out — \"{name}\"": "拨出连接 — “{name}”",
  "Dial-out: {state} — click to manage (ssh stays as rescue)": "拨出连接：{state} — 点击管理（ssh 仍保留作为救援通道）",
  "Discovery failed: {err}": "发现失败：{err}",
  "Drive ID (advanced)": "Drive ID（高级）",
  "Enter a port (5173) or ip:port (10.0.0.5:8080)": "请输入端口（如 5173）或 ip:port（如 10.0.0.5:8080）",
  "Forwarded {p} → {u}": "已转发 {p} → {u}",
  "Goal not confirmed — the session may be unresponsive. Your command was restored to the input.": "目标未确认——该会话可能没有响应。你的指令已还原到输入框。",
  "Installing on the machine…": "正在机器上安装…",
  "Installs the VibeSpace daemon as a persistent service on the machine so it <b>dials back to this instance over a WebSocket</b>. Every file/discovery/transcript op then uses that link — no ssh banner-hang, ControlMaster staleness, or per-op child processes. <b>ssh is kept</b> as the bootstrap + rescue channel, and you can remove this anytime.": "在机器上把 VibeSpace 守护进程安装为持久化服务，使它<b>通过 WebSocket 拨回本实例</b>。此后文件/发现/转录等操作都走这条链路——不再有 ssh banner 卡住、ControlMaster 陈旧、或每次操作都开子进程的问题。<b>ssh 仍会保留</b>作为引导与救援通道，随时可以移除此项。",
  "Jumping to that point in the conversation…": "正在跳转到对话中的那个位置…",
  "Last known scan — {host} was unreachable.": "最后一次已知扫描 — {host} 当时不可达。",
  "Loading earlier messages…": "正在加载更早的消息…",
  "Loading history from {host}…": "正在从 {host} 加载历史…",
  "Loading history from {host}… (large conversations can take a while)": "正在从 {host} 加载历史…（大型对话可能需要一些时间）",
  "Loading messages…": "正在加载消息…",
  "Loading {path}…": "正在加载 {path}…",
  "Model not reported yet — send a message first, then lock": "尚未报告模型——请先发送一条消息，再锁定",
  "No transcript found for this agent.": "未找到该 agent 的转录。",
  "Nothing to apply — {n} marked session(s) could no longer be found": "没有可应用的操作 — 已标记的 {n} 个会话已不存在",
  "Notify when a machine opens a new port": "机器新开放端口时通知我",
  "One-shot scan — click ⟳ to re-scan this host.": "一次性扫描 — 点击 ⟳ 重新扫描此主机。",
  "Opening session…": "正在打开会话…",
  "Opening the connection — this can take a few seconds": "正在建立连接 — 可能需要几秒钟",
  "Pooled accounts run on the local machine only.": "池化账号只能在本机运行。",
  "Prices not saved: {msg}": "单价未保存：{msg}",
  "Quota refresh failed for {n} target(s): {details}": "{n} 个目标的配额刷新失败：{details}",
  "Re-mint it in Manage agents (⋯ → Long-lived token).": "在 Manage agents 中重新生成（⋯ → 长期 token）。",
  "Re-scan sessions on this host": "重新扫描此主机上的会话",
  "Re-scanning {host}…": "正在重新扫描 {host}…",
  "Remote sessions are scanned once, not polled.": "远程会话只扫描一次，不会持续轮询。",
