  "Resuming the conversation…": "正在恢复对话…",
  "Scanning sessions over ssh…": "正在通过 ssh 扫描会话…",
  "Scanning this host…": "正在扫描此主机…",
  "Search on {host} failed.": "在 {host} 上的搜索失败。",
  "Searching {host}…": "正在搜索 {host}…",
  "Server error {code}": "服务器错误 {code}",
  "Server unreachable — nothing was changed": "服务器不可达——未做任何更改",
  "Session list may be out of date — the server is not responding.": "会话列表可能已过期——服务器无响应。",
  "Session states may have changed since this scan.": "自本次扫描以来，会话状态可能已发生变化。",
  "Setting goal…": "正在设置目标…",
  "Showing cached results — {host} is unreachable.": "正在显示缓存结果 — {host} 不可达。",
  "Starting the session on {host}… (installing tools / checking the conversation)": "正在 {host} 上启动会话…（安装工具 / 检查对话）",
  "Starting the session…": "正在启动会话…",
  "Still checking which accounts this session’s machine can use — this row is a guess until it answers.": "仍在检查此会话所在机器能使用哪些账号——在它响应之前，此行只是猜测。",
  "Still loading the transcript…": "转录仍在加载中…",
  "Still loading this agent's transcript — the machine holding it may be slow or unreachable.": "该 agent 的转录仍在加载——持有它的机器可能较慢或不可达。",
  "Still loading — {host} may be slow to hand over the transcript.": "仍在加载 — {host} 传出转录的速度可能较慢。",
  "Still starting the session on {host} — this can take a minute on a slow machine. Leave the window open.": "仍在 {host} 上启动会话 — 在较慢的机器上可能需要一分钟左右。请保持此窗口打开。",
  "Stopped watching for the login after 5 min. If you completed it, press Re-check in Manage agents to finish capturing it.": "已在 5 分钟后停止等待登录。如果你已完成登录，请在 Manage agents 中点击“重新检查”以完成捕获。",
  "Stopped watching {host} for the login after 5 min. If you finished signing in there, press Re-check to pick it up.": "已在 5 分钟后停止等待 {host} 上的登录。如果你已在那里完成登录，请点击“重新检查”以捕获它。",
  "Storage added, but connecting failed: {msg}": "存储已添加，但连接失败：{msg}",
  "The daemon is installed but <b>not currently dialed in</b> — ops fall back to ssh until it reconnects (it retries from the machine side).": "守护进程已安装，但<b>当前未拨入</b>——操作会回退到 ssh，直到它重新连接（由机器一侧自动重试）。",
  "The daemon on this machine is <b>dialing in</b> — data-plane ops (files, discovery, transcripts) ride that ws link instead of ssh. ssh stays as the rescue channel.": "这台机器上的守护进程正在<b>拨入</b>——数据面操作（文件、发现、转录）会走这条 ws 链路而非 ssh。ssh 仍作为救援通道保留。",
  "The login held on this machine for this account belongs to someone else — re-run “Log in on host as this account”.": "本机上为该账号持有的登录实际上属于另一个人 — 请重新执行“以此账号在主机上登录”。",
  "The nudge only fires when the session has not updated its board status for this long, and never after a turn that already reported. 0 = always stale (with cooldown 0: fires on every stop of a turn that did not report).": "只有当会话的状态板超过这个时长没有更新时才触发提醒，且本轮已汇报过时从不触发。0 = 永远视为过期（冷却也为 0 时：每个未汇报的轮次结束都触发）。",
  "The reasons below are guesses from cached data until the machine answers. Retrying shortly.": "在机器响应之前，下方的原因均为根据缓存数据的猜测。稍后会重试。",
  "The {backend} accounts list failed to render — {reason}": "{backend} 账号列表渲染失败 — {reason}",
  "This account is signed in elsewhere — log it in on this machine, or run the session where it is signed in.": "该账号在别处已登录——请在本机登录它，或把会话跑在它已登录的那台机器上。",
  "This instance's public address (for reverse mounts)": "本实例的公网地址（用于反向挂载）",
  "This machine was unreachable — showing the last successful scan, so this session may have changed or ended since.": "此机器当时不可达——正在显示最后一次成功的扫描结果，因此该会话此后可能已发生变化或已结束。",
  "Upgrade \"{name}\" to dial-out": "将“{name}”升级为拨出连接",
  "Upgrade \"{name}\" to dial-out (faster + self-healing over a flaky link; ssh kept as rescue)": "将“{name}”升级为拨出连接（在不稳定链路上更快、可自愈；ssh 仍保留作为救援通道）",
  "Upgrade to dial-out": "升级为拨出连接",
  "VS Code-style port discovery: linked machines (paired devices / connected hosts) are checked every ~30s, and a service that STARTS listening (a dev server, a database) shows a toast offering to forward it. Ports above 32767 and ports already forwarded are ignored. Turn off to stop the background checks.": "VS Code 风格的端口发现：每约 30 秒检查一次已连接的机器（配对设备 / 已连接主机），当有服务开始监听（如开发服务器、数据库）时会弹出提示，询问是否转发。32767 以上的端口和已转发的端口会被忽略。关闭可停止后台检查。",
  "Working…": "处理中…",
