  "{host}: ledger harvest failing ({msg}) — its usage below is last-known, not current": "{host}：账本采集失败（{msg}）——下方用量为最后已知值，非实时",
  "{n} marked session(s) will be skipped — they are no longer in the list.": "已标记的 {n} 个会话将被跳过——它们已不在列表中。",
