  "Agent tool: vibespace-job (background work)": "Agent 工具: vibespace-job（后台工作）",
  "Lets agents register services, long tasks and cron schedules that outlive their conversation (Background Work window). OFF: not taught, endpoints refuse with skip-and-continue guidance; existing jobs keep running and stay visible to you.": "允许 agent 注册可脱离对话存活的服务/长任务/定时任务（后台工作窗口）。关闭后：不教授该工具，端点拒绝并引导跳过；已存在的任务继续运行且你仍可见。",
