  "Capabilities of {name}": "{name} 的能力",
  "Enable \"{name}\" (trusted)?": "以信任方式启用「{name}」？",
  "This plugin declares:": "该插件声明：",
  "This plugin asks for more than the sandbox gives. Enable it only if you trust its author:": "该插件申请的能力超出沙箱。仅在你信任其作者时启用：",
  "Trusted code has the same power as VibeSpace itself. There is no undo beyond disabling it.": "受信代码拥有与 VibeSpace 本身相同的权力。除了禁用它没有其他撤销手段。",
  "Trusted since {when}": "自 {when} 起信任",
  "Plugin {id} failed to load: {error}": "插件 {id} 加载失败：{error}",
  "Plugin window not available: {id}": "插件窗口不可用：{id}",
  "Plugin: {name}": "插件：{name}",
  "Trusted client code: runs in this page with the same access as VibeSpace itself — it can read everything this page can, including your session, and act as you. Equivalent to adding code to VibeSpace.": "受信客户端代码：在本页面中运行，拥有与 VibeSpace 相同的访问权 — 能读取本页面能读取的一切（包括你的会话）并以你的身份操作。等同于给 VibeSpace 加代码。",
  "Sandboxed UI: its windows run in an isolated origin and cannot read this page.": "沙箱 UI：其窗口运行在隔离源中，无法读取本页面。",
  "Runs its own server process, confined to its plugin folder and its data folder.": "运行自己的服务端进程，限制在其插件文件夹和数据文件夹内。",
  "Server: read files under {paths}": "服务端：读取 {paths} 下的文件",
  "Server: write AND read files under {paths}": "服务端：写入并读取 {paths} 下的文件",
  "Server: run other programs (child processes) — those programs are NOT confined and can reach anything the server user can.": "服务端：运行其他程序（子进程）— 这些程序不受限制，服务器用户能访问的它都能访问。",
  "Server: network access to {hosts} — declared only; the sandbox does not restrict network access.": "服务端：访问网络 {hosts} — 仅声明；沙箱不限制网络访问。",
  "Adds agent tools every session can call: {names} — installed as programs on every session's PATH (this machine, ssh hosts and paired devices) and run OUTSIDE the plugin sandbox.": "添加每个会话都能调用的 agent 工具：{names} — 会作为程序安装进每个会话的 PATH（本机、ssh 主机与已配对设备），并在插件沙箱之外运行。",
  "This is a different package under the same id — it was left disabled. Review what it asks for and enable it again.": "这是同一 id 下的另一个包 — 已保持禁用。请复核它索取的能力后重新启用。",
  "No special capabilities declared.": "未声明特殊能力。",
  "not started": "未开始",
  "No window running yet — a reset time appears after the first request": "尚无运行中的窗口 — 第一次请求后才会出现重置时间",
