  "This rung’s display cannot resize: the app is fitted to the fixed framebuffer and scaled in the browser. With TigerVNC (Xvnc) the display follows the window.": "这一级的显示无法改变尺寸：应用已贴合到固定的帧缓冲并在浏览器里缩放。装了 TigerVNC（Xvnc）显示会跟随窗口。",
