  "Push…": "推送…",
  "Push lane — {label}": "推送通道 — {label}",
  "The claim was withdrawn by measurement. Re-declaring it clears the counters and retries the lane once.": "这个声明已被度量撤回。重新声明会清零计数器并重试通道一次。",
  "Exclusivity declaration": "独占度声明",
  "unknown — declare nothing: push only kicks the cursor (default)": "unknown —— 不做声明: 推送只推进游标(默认)",
  "shared — other clients use this app: push only kicks the cursor": "shared —— 别的客户端也在用这个应用: 推送只推进游标",
  "exclusive — this instance is the only client: push carries messages, the poll reconciles every 15 min": "exclusive — 这个实例是唯一客户端: 推送携带消息, 轮询每 15 分钟对账",
  "The platform does not say how many clients share the app, so exclusivity is asserted here and MEASURED by the product: records the reconciliation poll sees before push do not happen on an exclusive lane. Past 2% over 20 records the lane demotes itself to cursor kicks and says so.": "平台不告诉我们有几个客户端共用这个应用, 所以独占度在这里由你断言、由产品度量: 真正独占的通道上不会有先被对账轮询看到的记录。20 条样本以上超过 2% 时通道会自己降级成只推进游标, 并说出来。",
  "Add rule": "添加规则",
  "Agent · {name}": "Agent · {name}",
  "Assign & filter…": "分配与过滤…",
  "Authority": "权限",
  "Coalesce pushed messages before waking an agent (seconds)": "唤醒 agent 之前合并推送来的消息(秒)",
