  "{kind} · {name} (not live now)": "{kind} · {name}(此刻不在线)",
  "{n} matched message(s) are waiting for the next window or turn": "{n} 条匹配的消息在等下一个窗口或 turn",
  "~{n}/day would wake (of ~{m}/day)": "约 {n}/天会唤醒(共约 {m}/天)",
  "(a guard setting could not be read: {why} — review, fail closed)": "(有一项护栏设置读不出来: {why} —— 按审批处理, 保守拒绝)",
  "(the stored policy value was not understood — review, fail closed)": "(存下来的策略值无法理解 —— 按审批处理, 保守拒绝)",
  "A proposal carrying an attachment goes to review even on a \"send directly\" channel.": "带附件的提案即使在“直接发送”的频道上也要经过审批。",
  "A proposal whose text carries a link goes to review even on a channel whose policy is \"send directly\". A guard can only tighten a policy, never relax it.": "正文带链接的提案即使在策略为“直接发送”的频道上也要经过审批。护栏只能让策略更严, 绝不放宽。",
  "Access requests": "访问请求",
  "An IANA zone such as Asia/Shanghai or America/Los_Angeles. Outside working hours every proposal goes to review. Leave empty and nothing is guessed: a wrong zone would silently send everything (or nothing) to review.": "IANA 时区, 如 Asia/Shanghai 或 America/Los_Angeles。非工作时间内每条提案都要审批。留空则不做任何猜测: 错误的时区会静默地把所有东西(或什么都不)送去审批。",
