  "The ONE permanent deletion — the directory and its cookies are gone for good": "唯一的永久删除 —— 目录连同它的 cookie 一去不返",
  "Delete {name} permanently?": "永久删除 {name}?",
  "This removes the set-aside directory for good — its cookies and logins with it. There is no undo.": "这会永久移除该搁置目录 —— 连同它的 cookie 与登录态。无法撤销。",
