  "Unregistered directories": "未登记的目录",
  "under {base} — a Chromium profile no record names; adopt the ones worth keeping, set the rest aside": "位于 {base} —— 没有任何记录指向的 Chromium 配置目录; 收编值得留下的, 其余搁置",
  "None — every profile directory here is named by a record.": "没有 —— 这里的每个配置目录都有记录指向。",
  "moved beside themselves, never deleted by a sweep — only by your click": "已挪到自身旁边, 清扫绝不删除它们 —— 只有你的点击会",
  "Nothing set aside.": "没有搁置的目录。",
  "Sweep": "清扫",
  "No sweep has run yet (it runs at boot and every hour).": "还没有执行过清扫(启动时以及每小时执行一次)。",
  "Sweep failed": "清扫失败",
  "not recorded until {time}: {why}": "未记录，直到 {time}：{why}",
  "not traced — this browser was not started through VibeSpace (Agent browser)": "未记录 —— 这个浏览器不是由 VibeSpace 启动的（见“Agent 浏览器”）",
  "Actions are recorded only for browsers VibeSpace started (profiles) — this call drove a browser of its own.": "只有 VibeSpace 启动的浏览器（配置）才会记录操作 —— 这次调用驱动的是它自己的浏览器。",
  "Drag to resize the panes — double-click to even them out, right-click for Unsplit / Swap": "拖动调整两格宽度 — 双击均分，右键取消并排 / 交换左右",
  "Agent browser…": "Agent 浏览器…",
  "Shown side by side": "并排显示中",
  "Unbind": "解除并排",
  "Snap beside {name}": "并排到 {name} 旁",
  "its session": "它的会话",
  "Back to two free windows — the group stays and nothing moves": "回到两个独立窗口 — 分组保留, 什么都不会移动",
  "Show this browser side by side with its session, in one window": "把这个浏览器和它的会话并排放在同一个窗口里",
  "Open the session’s window first — there is nothing to snap beside": "先打开这个会话的窗口 — 现在没有可以并排的对象",
  "Open the live view beside the session when its browser starts": "浏览器启动时把实时视图并排打开在会话旁",
  "ON (default): when a session attaches a browser profile and its window is open on the desktop you are looking at, the live view opens bound beside it — two panes in one window, so the browser never loses its owner. OFF: open it yourself (session menu → Agent browser — live view) and bind it with \"Snap beside\" (or group it with the session's window as tabs, then choose \"Show side by side\"). An ephemeral browser (no profile) is never auto-opened.": "开(默认): 当某个会话挂载了浏览器配置且它的窗口就开在你正看着的桌面上时, 实时视图会绑定着并排打开 — 同一个窗口里的两格, 浏览器永远不会丢掉它的主人. 关: 自己打开(会话菜单 → Agent 浏览器 — 实时视图), 再用“并排到…旁”来绑定(或先把它和会话窗口合并成标签组, 再选“并排显示”). 临时浏览器(无配置)永远不会自动打开.",
  "VibeSpace-started window": "VibeSpace 启动的窗口",
  "⚠ Let agents address windows on your real desktop (tier 3)": "⚠ 允许 agent 操作你真实桌面上的窗口（第 3 级）",
  "OFF (default): an agent may act only in windows VibeSpace started on its own private displays; your own desktop is never listed. ON: every application on this machine’s accessibility bus becomes a window target an agent can read (its accessibility tree contains the text on your screen) and act in through the actions a node itself declares — including the window you are typing in. Nothing is ever injected on this class (no chords, no point clicks); every such row is marked “your desktop”; you can pause an agent per window (Desktop apps → Agents on your real desktop); turning this OFF drops every such lease at once.": "关闭（默认）：agent 只能操作 VibeSpace 在自己私有显示上启动的窗口，你的桌面永远不会被列出。开启：本机无障碍总线上的每个应用都成为 agent 可读取（其无障碍树包含你屏幕上的文字）并通过节点自身声明的动作来操作的窗口目标——包括你正在输入的那个窗口。这一类永远不会注入任何输入（没有组合键，没有坐标点击）；每一行都标记为“你的桌面”；你可以按窗口暂停 agent（桌面应用 → 你真实桌面上的 agent）；关闭此开关会立即撤销所有此类租约。",
  "Agents on your real desktop": "你真实桌面上的 agent",
