  "started {ago}": "{ago}启动",
  "Not running": "未运行",
  "Could not stop the browser": "无法停止浏览器",
  "Stopped {label}": "已停止 {label}",
  "Stop this browser now — the conversation's next command starts it again (a login in it is gone)": "立即停止这个浏览器 — 该对话的下一条命令会重新启动它（其中的登录会丢失）",
  "Ephemeral browsers": "临时浏览器",
  "one per conversation that browses without a profile — started by its first command, stopped after its idle timeout, removed with the conversation": "每个不使用 profile 浏览的对话一个 — 由它的第一条命令启动，空闲超时后停止，随对话一起移除",
  "None — no conversation has browsed without a profile since its start.": "没有 — 自启动以来没有对话在不使用 profile 的情况下浏览。",
