  "Open a web view": "打开网页视图",
  "No display backend on {machine} ({why})": "{machine}上没有显示后端（{why}）",
  "Windows on {machine} will use {backend} — {why}": "{machine}上的窗口将使用 {backend} — {why}",
  "Windows on {machine} will use {backend}": "{machine}上的窗口将使用 {backend}",
  "needs the agent upgraded": "需要升级 agent",
  "no X11 (macOS / Windows)": "没有 X11（macOS / Windows）",
  "connects when chosen": "选中时连接",
  "The VibeSpace agent on {machine} is too old to run desktop apps — reconnect the machine to upgrade it": "{machine}上的 VibeSpace agent 版本太旧，无法运行桌面应用 — 重新连接这台机器以升级它",
  "{machine} is not answering: {why}": "{machine}没有响应：{why}",
  "{machine} is not a machine on this instance": "{machine}不是本实例上的机器",
  "Could not reach {machine}": "无法连接{machine}",
  "This machine runs macOS or Windows — it has no X11 server, so desktop apps cannot run there.": "这台机器运行 macOS 或 Windows — 没有 X11 服务器，桌面应用无法在上面运行。",
  "This Linux has no apt-get — install xpra 6.x by hand from xpra.org.": "这个 Linux 没有 apt-get — 请从 xpra.org 手动安装 xpra 6.x。",
  "Its package sources offer only an old xpra and xpra.org publishes nothing for this release — install xpra 6.x by hand.": "它的软件源只有旧版 xpra，且 xpra.org 没有为这个发行版发布软件包 — 请手动安装 xpra 6.x。",
  "This machine has no passwordless sudo — run these commands yourself in a terminal there, then check again.": "这台机器没有免密 sudo — 请在那台机器的终端里自己运行这些命令，然后再检查一次。",
  "An install is already running on this machine — wait for it to finish, then check again.": "这台机器上已有一个安装正在进行 — 请等它结束后再检查一次。",
  "The install did not finish in time and is still running on this machine — VibeSpace never stops apt halfway. Check again once it ends.": "安装没有在限定时间内完成，仍在这台机器上运行 — VibeSpace 绝不会中途停止 apt。等它结束后再检查一次。",
  "The link to this machine dropped during the install. The install keeps running there — once the machine is back and has finished it, check again.": "安装过程中与这台机器的连接断开了。安装仍在那里继续运行 — 等这台机器重新连上、安装结束后，再检查一次。",
  "The install ended without saying how (it was stopped, or the machine restarted) — check again.": "安装结束了，但没有留下结果（它被停止了，或者机器重启了）— 请再检查一次。",
  "An install is already running on {machine} — follow its log here.": "{machine}上已有一个安装正在进行 — 在这里查看它的日志。",
  "Follow the install": "查看这次安装",
  "Still installing on {machine} — re-attached. Its log so far follows.": "{machine}上仍在安装 — 已重新接上。下面是到目前为止的日志。",
  "The agent on this machine did not report what it runs — reconnect it to upgrade the agent.": "这台机器上的 agent 没有报告它的系统信息 — 重新连接以升级 agent。",
  "Run on": "运行于",
  "Install xpra on {machine}…": "在{machine}上安装 xpra…",
  "Shows the install plan first — nothing runs until you confirm": "先显示安装计划 — 确认之前什么都不会运行",
  "on {machine}": "在{machine}上",
  "machine not answering": "机器无响应",
  "Install xpra on {machine}": "在{machine}上安装 xpra",
