  "{label} — on {machine}": "{label} — 在 {machine} 上",
  "{machine} is not answering": "{machine} 没有响应",
  "The machine this app runs on is not answering — the app may still be running there; the window reconnects when it returns": "运行这个应用的机器没有响应 — 应用可能仍在那里运行；机器恢复后窗口会重新连接",
  "Could not save the window frame choice": "无法保存窗口边框设置",
