  "Frame hidden — the app draws its own title bar": "边框已隐藏 — 应用自带标题栏",
  "Frame shown while an agent drives this app": "agent 操作此应用期间显示边框",
  "Frame shown in a tab group": "在标签组中显示边框",
  "Frame shown on a small screen": "小屏幕上显示边框",
  "Frame shown until the picture is connected": "画面连接前显示边框",
  "Frame shown (Settings → Seamless desktop app windows is off)": "显示边框（设置 → 无缝桌面应用窗口 已关闭）",
  "Frame shown (your choice for this app)": "显示边框（你为此应用的选择）",
  "Frame shown — the app has no title bar of its own": "显示边框 — 应用没有自己的标题栏",
