  "Stop app": "停止应用",
  "{app} stops in under a minute without input — Keep running is in the window menu": "{app} 若无输入将在一分钟内停止 — “保持运行”在窗口菜单中",
  "Auto (apps that draw their own title bar)": "自动（自带标题栏的应用）",
  "Off (always show the window frame)": "关闭（始终显示窗口边框）",
  "Seamless desktop app windows": "无缝桌面应用窗口",
  "An app that draws its own title bar (GTK header bars, e.g. GNOME Calculator) is shown with NO VibeSpace title bar or status strip: drag its own header bar to move the window. Hover the top edge (or hold Alt) to bring the bars back; the taskbar menu of the window has every control. Paused while an agent drives the app, in a tab group and on a phone. A window's ⋯ → Show window frame overrides this per app.": "自带标题栏的应用（GTK header bar，例如 GNOME 计算器）显示时不带 VibeSpace 的标题栏和状态条：拖动它自己的标题栏即可移动窗口。悬停在窗口顶边（或按住 Alt）可让这两条栏重新出现；窗口的任务栏菜单包含所有控制项。agent 操作应用时、在标签组中以及在手机上会暂停。窗口的 ⋯ → 显示窗口边框 可按应用覆盖此设置。",
  "Typing goes to the browser": "输入会发送到浏览器",
  "While you drive, every key goes to the page. Press a chat box or a terminal to type there instead — the browser stays yours; click the picture to come back (Ctrl+Backslash and Ctrl+Alt+Left/Right stay the app’s).": "你操作期间，每个按键都发送到网页。点一下聊天框或终端就能改在那里输入 — 浏览器仍由你接管；点画面即可回到网页（Ctrl+反斜杠 和 Ctrl+Alt+左/右 仍归应用使用）。",
  "Keyboard input for the agent’s browser": "发往 agent 浏览器的键盘输入",
  "input sent · {n}": "已发送输入 · {n}",
  "not sent — {why}": "未发送 — {why}",
  "no connection": "无连接",
  "the live view is disconnected": "实时画面已断开连接",
  "Not pasted into the page: {n} characters is more than one paste may carry ({max})": "未粘贴到网页：{n} 个字符超过了单次粘贴的上限（{max}）",
  "Not run — it waited while you drove the browser and the page changed. The agent re-plans from the handback.": "未执行 — 它在你操作浏览器期间一直在等待，而页面已经变了。agent 会根据交还消息重新规划。",
  "Not run — you took over the browser, so this step went stale. The agent re-plans after you hand back.": "未执行 — 你接管了浏览器，这一步已经过时。你交还后 agent 会重新规划。",
  "App default": "应用默认",
  "Scale {scale}× — the default you chose for this app — widgets {gdk}×, text at {dpi} dpi.": "缩放 {scale}×，你为此应用选定的默认值 —— 控件 {gdk}×，文字 {dpi} dpi。",
  "{scale}× is this app’s default": "{scale}× 是此应用的默认缩放",
  "Make {scale}× the default for this app": "把 {scale}× 设为此应用的默认缩放",
  "Forget this app’s default ({scale}×)": "取消此应用的默认缩放（{scale}×）",
  "Could not save the app’s default scale": "无法保存此应用的默认缩放",
  "Could not save the choice": "无法保存此选择",
  "Default scale for {app}": "{app} 的默认缩放",
  "Default scale for {app}: Auto (Settings → Desktop app scale). Click to choose the scale it starts at.": "{app} 的默认缩放：自动（设置 → 桌面应用缩放）。点击可选择它启动时的缩放。",
  "Default scale for {app}: {scale}× — it starts at this scale. Click to change.": "{app} 的默认缩放：{scale}× —— 它会以此缩放启动。点击可更改。",
  "Auto (Settings → Desktop app scale)": "自动（设置 → 桌面应用缩放）",
  "Tabs (then offer side by side)": "标签（随后提示可并排）",
  "Side by side at once": "直接并排",
  "Dropping a window onto another": "把窗口拖到另一个窗口上",
  "What a window dragged onto another window's icon or tab bar becomes: grouped as tabs (a toast offers \"Show side by side\"), or shown side by side at once — the dragged window on the right, with Undo (it goes back where it was) and Unsplit (stay grouped as tabs).": "拖到另一个窗口的图标或标签栏上的窗口会变成什么：合并为标签（随后一条提示提供「并排显示」），或直接并排显示——被拖的窗口在右侧，提示里有「撤销」（它回到原来的位置）和「取消并排」（保持为标签组）。",
  "Side by side with the window": "与该窗口并排",
  "As a tab of the window": "作为该窗口的标签",
  "In its own window": "在独立窗口中",
  "Opening a file path or link from a window": "从窗口打开文件路径或链接",
  "Where a file or folder opened from a chat (a path or a local link) appears: beside that chat window (the side it is not on, if it is already side by side), as a tab next to it, or in its own free window. Opening the same path again from the same window shows the tab it is already in. The phone always opens its own window.": "从对话中打开的文件或文件夹（路径或本地链接）出现在哪里：在该对话窗口旁并排（如果它已经并排，则放在它不在的那一侧）、作为它旁边的标签，或在独立的窗口中。从同一窗口再次打开同一路径时，显示它已所在的标签。手机上始终在独立窗口中打开。",
