  "last sync {ago}": "上次同步 {ago}",
  "The sign-in renews itself while this instance runs — re-authorize only if the instance is off for more than {days} days.": "本实例运行期间登录会自动续期 —— 只有实例停机超过 {days} 天才需要重新授权。",
