  "No groups yet. \"New group\" starts one with live agent sessions; an agent can too (vibespace-msg group create). Every conversation of an account you connect below appears here as well.": "还没有群。「新建群」可以拉正在运行的 agent 会话建一个；agent 也可以自己建（vibespace-msg group create）。你在下方连接的账号里的每个会话也都会出现在这里。",
