  "You took over — {n} agent operation(s) interrupted: {verbs}. The agent waits until you hand back": "你已接管 — 打断了 agent 的 {n} 个操作: {verbs}。在你交还之前 agent 会等待",
  "A script running in the page was stopped with it.": "页面里正在运行的一段脚本也随之被停止。",
  "Your takeover lapsed (no input) — the agent is driving again and was told to re-run: {verbs}": "你的接管已失效(无输入) — agent 重新接手, 并已被告知重新运行: {verbs}",
  "Control handed back to the agent — it was told to re-run: {verbs}": "已把控制交还给 agent — 它已被告知重新运行: {verbs}",
  // lane R5 (2026-09-26): the per-second pace, the vendor's rate refusal, the first read
  "Gmail: quota units per second per account": "Gmail：每个账号每秒配额单位",
  "Reads are spread evenly: at most this many quota units a second (a thread read costs 40, so 40 = one thread a second), and never faster than the per-minute budget above allows. Google refuses bursts well inside its 6000-a-minute cap; when it does, the account waits a few seconds and the card says so.": "读取均匀摊开：每秒最多这么多配额单位（读一个邮件会话花 40，所以 40 = 每秒一个会话），也绝不快于上面的每分钟额度。Google 会拒绝远低于其每分钟 6000 上限的突发读取；被拒时账号只等几秒，卡片上会说明。",
  "Lark: requests per second per account": "飞书：每个账号每秒请求数",
  "Requests are spread evenly: at most this many a second, and never faster than the per-minute budget above allows. Lark allows 50 a second per API for the whole app across every instance and user that shares it.": "请求均匀摊开：每秒最多这么多次，也绝不快于上面的每分钟额度。飞书对整个应用（所有共用它的实例和用户合计）每个接口每秒允许 50 次。",
  "Google": "Google",
  "Lark": "Lark",
  "Feishu": "飞书",
  "Polling at {n} of {m} {unit}/min — {vendor} refused this account's quota at {time}; another instance may be polling the same account · back to {m} by {back}": "轮询速度 {n}/{m} {unit}/分钟 — {vendor} 在 {time} 拒绝了这个账号的配额；可能有另一个实例在轮询同一个账号 · {back} 前恢复到 {m}",
