  "Several profiles share this name; open the one you want from the Agent browser panel.": "有好几个配置叫这个名字，请在“Agent 浏览器”面板里点你要的那一个。",
  "Profiles saved on another computer can't be switched in this version.": "这个版本还不能切换保存在另一台电脑上的配置。",
