  "Last dial: refused ({reason}) at {time} — the device holds an older command; generate a new one": "最近一次拨号：被拒绝（{reason}），{time} — 设备上的命令已过期，请重新生成",
  "Last dial: refused ({reason}) at {time} — the device still holds a command older than the one generated at {minted}: run that one on the device (or generate a new one if you no longer have it)": "最近一次拨号：被拒绝（{reason}），{time} — 设备上仍是比 {minted} 生成的那条更旧的命令：请在设备上运行那一条（已经找不到了再重新生成）",
  "Offline since {time} — no dial attempt has reached this server since (is the device on, and on a network that reaches {host}?)": "自 {time} 起离线 — 此后没有任何拨号到达本服务器（设备开着吗？它的网络能访问 {host} 吗？）",
  "Never connected — the command generated at {time} has not reached this server (not run yet, or the device cannot reach {host})": "从未连接 — {time} 生成的命令尚未到达本服务器（还没运行，或设备无法访问 {host}）",
