  "The lists changed while this dialog was open (another window) — here they are as they are now; nothing was saved": "对话框打开期间列表被改动了（另一个窗口）— 这是现在的列表，什么都没保存",
  "At most 64 conversations and Task Groups per list": "每个列表最多 64 个会话和任务组",
