  "An agent points one command at this machine's network (vibespace-exit use / url) — the command runs here, only its traffic leaves from {machine}.": "agent 让一条命令走这台机器的网络（vibespace-exit use / url）— 命令在这里运行，只有流量从 {machine} 出去。",
  "An agent runs a shell command ON {machine}, as you, up to 30 s (vibespace-exit run).": "agent 以你的身份在 {machine} 上运行 shell 命令，最长 30 秒（vibespace-exit run）。",
  "Ask me each time": "每次都问我",
  "Every command waits for your Allow in \"For you\" (60 s, then it is refused).": "每条命令都会在“给你”里等你点允许（60 秒后自动拒绝）。",
  "{n} conversation(s) using it now will lose it when you save": "现在正在使用它的 {n} 个会话会在保存后失去它",
  "Who can use {machine}: network — {a}; commands — {b}": "谁能使用 {machine}：网络 — {a}；命令 — {b}",
  "from {addr}": "来自 {addr}",
  "KEY REFUSED": "密钥被拒",
  "REFUSED": "被拒绝",
  "Pairing command — see the dial state, pick an address, generate a new command (keeps the row)": "配对命令 — 查看拨号状态、选择地址、生成新命令（保留这一行）",
  "Who can use \"{name}\" as an exit…": "谁能把 \"{name}\" 当出口使用…",
  "dial-out device": "拨出式设备",
  "Send the new command to the connected device over its link (it keeps working without running anything)": "把新命令通过它的连接发给当前已连上的设备（无需在设备上运行任何东西，它会继续工作）",
  "Unchecked: the connected device is disconnected now and its command stops working — run the new command on the device yourself.": "不勾选：当前连着的设备会立即断开，它的命令随即失效 — 请你自己在设备上运行新命令。",
  "A new command for \"{id}\" — the device that was connected has been disconnected; it holds the previous command, which no longer works. Run this on the device:": "\"{id}\" 的新命令 — 原本连着的设备已被断开；它持有的上一条命令已失效。在设备上运行这条：",
  "A new command for \"{id}\" — the one you generated before stops working now. Run this on the device:": "\"{id}\" 的新命令 — 之前生成的那条现在已失效。在设备上运行这条：",
  "Pairing command — \"{name}\"": "配对命令 — \"{name}\"",
  "Last run: {cmd} — {who}, {when}, not run — agent {v} cannot run commands on Windows; rerun the install command (Pairing command)": "上次运行：{cmd} — {who}，{when}，未运行 — 代理 {v} 无法在 Windows 上运行命令；请重新运行安装命令（配对命令）",
  "Agent {from} — its update to {to} failed, so commands cannot run here; rerun the install command (Pairing command)": "代理 {from} — 升级到 {to} 失败，因此这里无法运行命令；请重新运行安装命令（配对命令）",
  "Agent {from} — its update to {to} failed; rerun the install command (Pairing command)": "代理 {from} — 升级到 {to} 失败；请重新运行安装命令（配对命令）",
  "not run — the agent is too old to run commands on Windows; rerun the install command": "未运行 — 代理版本过旧，无法在 Windows 上运行命令；请重新运行安装命令",
  "{machine} stopped answering after its upgrade to {to} began — rerun its install command (Remote → {machine} → Pairing command)": "{machine}升级到{to}开始后就不再应答——请重新运行它的安装命令（远程 → {machine} → 配对命令）",
  "VibeSpace started updating the device agent on {machine} to {to}; the device has not connected since. This item resolves itself when it connects again.": "VibeSpace 已开始把{machine}上的设备代理升级到{to}；此后该设备一直没有连接。它重新连接后，此项会自动解决。",
  "{machine}: its agent could not update ({from} → {to})": "{machine}：代理无法升级（{from} → {to}）",
  "VibeSpace tried 3 times to update the device agent on {machine} from {from} to {to}; it stayed at {from}.": "VibeSpace 已 3 次尝试把 {machine} 上的设备代理从 {from} 升级到 {to}；它仍停在 {from}。",
  "What does not work there until it is updated: running commands (vibespace-exit run) — this agent cannot run them on Windows.": "升级之前那里无法使用的功能：运行命令（vibespace-exit run）— 这个代理无法在 Windows 上运行命令。",
  "The one step: rerun the device's install command (Remote → {machine} → Pairing command). This item resolves itself when the device reports {to}.": "唯一的一步：重新运行该设备的安装命令（远程 → {machine} → 配对命令）。设备报告 {to} 后，这一项会自动解决。",
  "Loading addresses…": "正在列出地址…",
  "The device checks the chosen address before it installs anything and stops with the reason if it cannot reach it — pick the one its network can see.": "设备会先检查所选地址再安装，连不上就停下并说明原因 — 选它的网络能看到的那个。",
