  "agent reactions are turned off for this account": "这个账号关闭了 agent 的表情回应",
  "Reactions: list calls per minute per account": "表情回应：每个账号每分钟的列表调用次数",
  "Reactions are read only for the messages an open window shows, one call per message, at most this many a minute per account (0 = never list — reactions arrive only as live events). Checked before the account's per-minute vendor budget, so reading reactions never takes the budget new messages need.": "只读取打开的窗口中可见消息的表情回应，每条消息一次调用，每个账号每分钟最多这么多次（0 = 从不拉取列表 — 表情回应只通过实时事件到达）。在该账号的每分钟平台额度之前判定，因此读取表情回应永远不会占用新消息所需的预算。",
  "Reactions: minutes a fetched list stays fresh": "表情回应：拉取的列表保持有效的分钟数",
  "A visible message whose reactions were read within this many minutes is not read again; the chips show the stored count and their tooltip says how old it is.": "可见消息的表情回应在这么多分钟内读过就不会再读；表情会显示已存储的数量，悬停提示会说明它有多旧。",
  "Threads: seconds between two loads of one thread": "话题：同一话题两次加载之间的秒数",
  "Opening a thread loads its replies from the vendor (where they are not listed with the conversation — Lark topics); the same thread is loaded again at most this often.": "打开话题时会从服务商加载它的回复（当回复不随会话一起列出时 — Lark 话题）；同一个话题最多这么频繁地再次加载。",
