  "The last 50 commands agents ran on {machine}, newest first; a row opens its output (the first 4 KiB of each stream).": "agent 在 {machine} 上运行的最近 50 条命令，最新的在最前；点开一行可看它的输出（每个流的前 4 KiB）。",
