  "Company presets: {parts}": "公司预设：{parts}",
  "Read from {dir} — it updates without a restart.": "读取自 {dir} —— 更新无需重启。",
  "No company OAuth client on this instance — ask your admin. Meanwhile the built-in client works, and your own avoids rclone's shared quota.": "本实例没有公司提供的 OAuth 客户端 —— 请联系你的管理员。在此之前可以用内置客户端，或用你自己的客户端避开 rclone 的共享配额。",
  "No company OAuth client on this instance — ask your admin, or provide your own (it needs the gmail.readonly scope).": "本实例没有公司提供的 OAuth 客户端 —— 请联系你的管理员，或提供你自己的客户端（需要 gmail.readonly 权限范围）。",
  "No company {name} client on this instance — ask your admin, or use your own client.": "本实例没有公司提供的 {name} 客户端 —— 请联系你的管理员，或使用你自己的客户端。",
  "a notice being retried": "一条正在重试投递的通知",
  "{n} notices being retried": "{n} 条正在重试投递的通知",
