  "A new, empty profile — this conversation's own browser is not moved; you sign in once in the new one.": "新建一个空的配置——此对话自己的浏览器不会被挪走；你需要在新配置里登录一次。",
  "This conversation's browser changed since this dialog opened — nothing was created; the dialog was reopened with the form that applies now.": "打开此对话框后，此对话的浏览器发生了变化——什么都没有创建；对话框已按现在适用的表单重新打开。",
