  "the chrome at {path}": "位于 {path} 的 chrome",
  "the browser CLI's default build": "浏览器 CLI 的默认版本",
  "{build} is no longer on this computer — it won't start until you choose another build (Change build…).": "{build} 已不在这台电脑上——在你换一个版本之前它无法启动（更换版本…）。",
