  "{choice} · running Chrome {version}": "{choice} · 正在运行 Chrome {version}",
  "The browser CLI's default build": "浏览器 CLI 的默认版本",
  "Whatever the browser CLI picks — usually the newest Chrome it installed.": "由浏览器 CLI 自己决定——通常是它安装的最新 Chrome。",
  "The list of Chrome builds could not be read.": "无法读取 Chrome 版本列表。",
  "Reading the list of Chrome builds…": "正在读取 Chrome 版本列表…",
