  "Its chrome file can't be run (not executable).": "它的 chrome 文件无法运行（没有执行权限）。",
  "Its folder has no chrome file.": "它的文件夹里没有 chrome 文件。",
  "Older than the Chrome that last opened this profile ({wrote}) — opening it there would damage its saved logins.": "比上次打开这个配置的 Chrome（{wrote}）旧——用它打开会损坏已保存的登录状态。",
  "No Chrome builds are installed there yet.": "那里还没有安装任何 Chrome 版本。",
