  "The .deb file’s full path on {machine} — in Files, right-click a .deb file and choose “Install this package…”, or type its path. Its plan shows what it installs and whether it runs its own install scripts.": "填写 .deb 文件在{machine}上的完整路径 — 也可以在“文件”里右键 .deb 文件，选择“安装这个包…”。计划会显示它安装什么，以及是否会运行自带的安装脚本。",
  "Show the plan": "显示计划",
  "Type the full path of a .deb file (it starts with / and ends with .deb)": "请输入 .deb 文件的完整路径（以 / 开头，以 .deb 结尾）",
  "A publisher’s own apt repository (for example a browser or an editor vendor). Its key is fetched and its fingerprint shown before anything is added.": "发布者自己的 apt 仓库（例如浏览器或编辑器厂商）。添加任何东西之前，会先获取它的密钥并显示指纹。",
