  "Let an agent help install an app": "让 agent 帮忙安装应用",
  "Starts a temporary helper conversation that knows how to install apps on {machine}. It can only propose an install — you approve it in For you. Close it when it says done.": "启动一个懂得如何在{machine}上安装应用的临时助手对话。它只能提议安装 — 由你在“待你处理”里批准。它说完成后就可以关掉。",
  "What do you want to install? (e.g. an image editor that opens PSD files)": "你想安装什么？（例如一个能打开 PSD 文件的图片编辑器）",
  "What do you want to install?": "你想安装什么？",
