  "Apps you install here are kept by VibeSpace: they come back by themselves after this machine is rebuilt. An agent can only propose one — you approve it.": "在这里安装的应用由 VibeSpace 保管：机器重建后会自动回来。agent 只能提议安装 — 由你批准。",
