  "{size} MB · installed by hand — VibeSpace removes only the builds it downloaded": "{size} MB · 手动安装——VibeSpace 只删除它自己下载的版本",
  "{free} GB free on {path}": "{path} 上可用 {free} GB",
  "Remove Chrome {version}?": "删除 Chrome {version}？",
  "Its folder ({size} MB) is deleted from this computer; no profile uses it. You can download it again later.": "它的文件夹（{size} MB）将从这台电脑上删除；没有配置文件在用它。以后可以再次下载。",
