  "Slack: requests per minute per account": "Slack：每个账号每分钟请求数",
  "Slack limits every method on its own (reading a conversation's history: 50 a minute for your own app). This is the account's whole minute across all of them; when an account reaches it, its refreshes wait for the next minute and the account card says so.": "Slack 对每个接口单独限流（读取会话历史：你自己的 app 每分钟 50 次）。这里是该账号所有接口加起来每分钟的上限；用满后刷新会等到下一分钟，账号卡片上会说明。",
  "Slack: requests per second per account": "Slack：每个账号每秒请求数",
  "Requests are spread evenly: at most this many a second, and never faster than the per-minute budget above allows.": "请求均匀分布：每秒最多这么多，且不会快过上面的每分钟预算。",
  "Used by the Slack channel": "供 Slack 渠道使用",
  "1. Press “Connect {label}” — Slack opens a page that makes your own app (pick your workspace, press Create).": "1. 按「连接 {label}」——Slack 会打开一个创建你自己 app 的页面（选择工作区，按 Create）。",
  "2. Press “Install to Workspace”, then Allow.": "2. 按「Install to Workspace」，再按 Allow。",
  "3. Copy the User OAuth Token (it starts xoxp-) from “OAuth & Permissions” and paste it in the box below.": "3. 在「OAuth & Permissions」页复制 User OAuth Token（以 xoxp- 开头），粘贴到下面的框里。",
  "Your workspace admin may have to approve the app; your company’s data policy comes first. The token stays on this server, sealed.": "工作区管理员可能需要批准这个 app；以你公司的数据政策为准。token 只加密保存在这台服务器上。",
  "The account record, its conversation list AND its local copy go away: the saved messages, the fetched files and its ended outbox proposals are deleted from this server ({provider}'s terms ask for it). Nothing is deleted on {provider}.": "账号记录、会话列表以及本地副本都会被移除：已保存的消息、已下载的文件和已结束的发件箱提议都会从这台服务器删除（{provider} 的条款要求如此）。{provider} 上的内容不会被删除。",
