  "This channel offers no “send directly”: every message an agent drafts here waits for your approval on the Outbox card.": "这个渠道不提供「直接发送」：agent 在这里起草的每条消息都要等你在发件箱卡片上批准。",
  "Stored on this server. Messages an agent reads are sent to that agent’s model provider (Anthropic for Claude, OpenAI for Codex) to answer, not for training. Removing the account deletes this copy.": "保存在这台服务器上。agent 读到的消息会发给该 agent 的模型厂商（Claude 是 Anthropic，Codex 是 OpenAI）用于回答，不用于训练。移除账号会删除这份副本。",
  "Free plan: {vendor} hides messages older than 90 days.": "免费版：{vendor} 会隐藏 90 天前的消息。",
  "{vendor} serves this app only 15 messages a minute (the limit for an app shared outside its workspace) — make your own app from the Connect link in this workspace.": "{vendor} 只给这个 app 每分钟 15 条消息（这是对分发到工作区外的 app 的限制）——请用连接链接在这个工作区里建你自己的 app。",
